using System;using System.Collections;using System.Collections.Generic;using System.Text;using System.Web.Script.Serialization;
public static class PublicResearchAudit {
 static Dictionary<string,object>D(object o){return o as Dictionary<string,object>??new Dictionary<string,object>();}
 static string S(Dictionary<string,object>d,string k){return d.ContainsKey(k)?Convert.ToString(d[k]):"";}
 static object V(Dictionary<string,object>d,string k){return d.ContainsKey(k)?d[k]:null;}
 static IEnumerable<object>A(object o){if(o is IEnumerable&&!(o is string)&&!(o is IDictionary))foreach(var x in (IEnumerable)o)yield return x;}
 public static string Describe(Dictionary<string,object>card){var b=new StringBuilder();foreach(var x in A(V(card,"public_research_versions"))){try{var wrap=D(x);string payload=S(wrap,"payload_json");if(payload==""||payload.Length>4194304||ProvenanceAudit.Sha(payload)!=S(wrap,"payload_sha256"))throw new Exception("Version payload hash mismatch");var version=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(payload);if(S(version,"research_id")!=S(card,"research_id"))throw new Exception("Version belongs to another card");b.AppendLine().AppendLine("НОВАЯ ВЕРСИЯ ИССЛЕДОВАНИЯ: "+S(version,"round")).AppendLine("Разбор сохранённых материалов: "+S(version,"derived_at")).AppendLine("Отдельно от прежнего входа AI и решений владельца. AUTO_ADMISSION=false; покупатели и спрос не доказаны.").AppendLine("SHA256 версии: "+S(wrap,"payload_sha256"));
 var originals=new HashSet<string>();foreach(var row in A(V(card,"observed_basis")))originals.Add(S(D(row),"url"));var docs=new HashSet<string>();
 foreach(string field in new[]{"sources","documents"})foreach(var row in A(V(version,field))){var r=D(row);string text=S(r,"text"),url=S(r,"url");if(ProvenanceAudit.Sha(text)!=S(r,"text_sha256"))throw new Exception("Source text hash mismatch");if(field=="sources"&&!originals.Contains(url))throw new Exception("Original URL outside card");if(field=="documents")docs.Add(url);b.AppendLine().AppendLine(field=="sources"?"ИСХОДНОЕ СООБЩЕНИЕ — новый снимок":"ДОКУМЕНТ АЛЬТЕРНАТИВЫ — не клиент").AppendLine(url).AppendLine("Автор/издатель (metadata): "+S(r,"author")+" | роль: "+S(r,"role")).AppendLine("Дата получения: "+S(r,"captured_at")+" | дата публикации: "+S(r,"published_at")).AppendLine("Полнота/границы: "+S(r,"text_scope")).AppendLine("codepoint [0,"+ProvenanceAudit.Count(text)+") | SHA256 текста: "+S(r,"text_sha256")).AppendLine("SHA256 исходного HTTP response: "+S(r,"response_sha256")).AppendLine(text);}
 b.AppendLine().AppendLine("СРАВНЕНИЕ С ЗАДАЧЕЙ АВТОРА — ручной разбор, не решение модели");foreach(var row in A(V(version,"comparisons"))){var r=D(row);if(!originals.Contains(S(r,"original_url")))throw new Exception("Comparison original outside card");b.AppendLine(S(r,"original_url")).AppendLine("Задача: "+S(r,"task_as_read")).AppendLine("Поддержанный вывод/неизвестное: "+S(r,"assessment"));foreach(var url in A(V(r,"document_urls"))){if(!docs.Contains(Convert.ToString(url)))throw new Exception("Comparison document missing");b.AppendLine("Документ: "+url);}b.AppendLine(S(r,"customer_or_demand"));}b.AppendLine(S(version,"routing_warning"));
 var diag=D(V(version,"diagnostic"));if(diag.Count>0)b.AppendLine().AppendLine("ЕДИНСТВЕННЫЙ CPU-ТЕСТ — ДИАГНОСТИКА, НЕ ДОПУСК").AppendLine(new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(diag)).AppendLine("Точный input/catalog/response/output: в общем списке «Происхождение AI», кейс qualified-comparison-001.");else b.AppendLine("В этой версии сохранён только сбор материалов. Смысловой разбор и CPU-тест для этого снимка не выполнялись; прежние сравнения не перенесены.");foreach(var error in A(V(version,"source_errors")))b.AppendLine("Недоступное исходное свидетельство: "+new JavaScriptSerializer().Serialize(error));foreach(var error in A(V(version,"document_errors")))b.AppendLine("Документ не прочитан целиком: "+new JavaScriptSerializer().Serialize(error));
 }catch(Exception ex){b.AppendLine("Новая версия недоступна для проверки: "+ex.Message+". Исходные данные не исправлялись.");}}return b.ToString();}
}
